% 0:clear environment
clc; clear; clf;


% 1: import data
old = double([11; 15; 19; 22; 24; 27; 28; 30; 31; 33; 35; 36; 37; 38; 39; 42; 43; 46; 49; 64]);
new = double([16; 21; 25; 27; 32; 34; 35; 36; 40; 41; 43; 44; 47; 48; 49; 50; 52; 54; 55; 61]);


% 2:transform array into table and check the value
T = table(old, new)
data = T{:, {'old', 'new'}};

% 2.1 missing check %[output:867e1a67]
nanCounts = sum(isnan(data), 1);
fprintf('NaN counts: Old=%d, New=%d\n', nanCounts); %[output:8a29dd65]

% 2.2 invalid check
infCounts = sum(isinf(data), 1);
fprintf('Inf counts: Old=%d, New=%d\n', infCounts);

% 2.3 check repeated rows
varNames = T.Properties.VariableNames;
numVars = width(T);

repeatedCols = false(1, numVars);

% transform from bubble sorting
for j = 2:numVars
    for i = 1:j-1
        % Comparison instead of exchange
        if ~repeatedCols(i) && isequaln(T.(varNames{i}), T.(varNames{j}))
            repeatedCols(j) = true;
            fprintf('repeated column: %s (same as %s)\n', varNames{j}, varNames{i});
            break;
        end
    end
end

numRepeateds = sum(repeatedCols);  % Count repeated columns

fprintf('Total repeated columns: %d\n', numRepeateds);

% 2.4 check sorted
oldSorted = issorted(T.old);
newSorted = issorted(T.new);

fprintf('Old sorted ascending: %d\n', oldSorted);
fprintf('New sorted ascending: %d\n', newSorted);


% 3: process with values
% 3.1 repeated processing
if any(repeatedCols)
    T_no_repeated_columns = T(:, ~repeatedCols);

    fprintf('Removed %d repeated columns.\n', ...
        sum(repeatedCols));
else
    T_no_repeated_columns = T;

    fprintf('No repeated columns removed.\n');
end

% 3.2 missing processing
if any(missingCounts > 0) %[output:group:83ae16c8]

    % extreme condition, entirely missing
    if any(missingCounts == height(T))
        error('entirely missing, cannot imputation.');
    end

    % use mean to fill the NAN
    T_clean = fillmissing(T, 'mean');
    fprintf('Filled %d missing values.\n', sum(missingCounts));

else
    T_clean = T;
    fprintf('No missing values found.\n'); %[output:6135c27d]
end %[output:group:83ae16c8]

% 3.3 inf processing
if any(isinf(data), 'all')
    error('Inf values detected. Please check the source data.');
end

% 3.4 sorting
if ~oldSorted
    T.old = sort(T.old, 'ascend');
    fprintf('Old has been sorted.\n');
end

if ~newSorted
    T.new = sort(T.new, 'ascend');
    fprintf('New has been sorted.\n');
end


% 4: data features
% 4.1 sample features
total_number = height(T_clean);  % total sample size
valid_old = sum(~ismissing(T_clean.old));  % valid sample size
valid_new = sum(~ismissing(T_clean.new));  
group_old = sum(~ismissing(T_clean.old));  % group sample size
group_new = sum(~ismissing(T_clean.new));  

% 4.2 basic feature
mean_old = mean(T_clean.old);  % mean
mean_new = mean(T_clean.new);

median_old = median(T_clean.old);  % median
median_new = median(T_clean.new);

mo_old = mode(T_clean.old);  % mode
mo_new = mode(T_clean.new);

% 4.3 discrete features
std_old = std(T_clean.old);  % standard deviation
std_new = std(T_clean.new);

var_old = var(T_clean.old);  % variance
var_new = var(T_clean.new);

iqr_old = iqr(T_clean.old);  % IQR
iqr_new = iqr(T_clean.new);

range_old = range(T_clean.old);  % range
range_new = range(T_clean.new);

cv_old = std(T_clean.old) / mean(T_clean.old) * 100;   % coefficient of variation, in percentage
cv_new = std(T_clean.new) / mean(T_clean.new) * 100;

% 4.4 range features
min_old = min(T_clean.old);  % min
min_new = min(T_clean.new);

max_old = max(T_clean.old);  % max
max_new = max(T_clean.new);

Q1_old = prctile(T_clean.old, 25);  % Q1
Q1_new = prctile(T_clean.new, 25);

Q3_old = prctile(T_clean.old, 75);  % Q3
Q3_new = prctile(T_clean.new, 75);


% 5: visualization of separate figures
% 5.1 values comparison  Q:这里数据是有序的，无序是否需要排序？
figure('Name', 'Values by Row', 'NumberTitle', 'off'); %[output:9a045229]
idx = (1:size(T_clean, 1))';

hold on; %[output:9a045229]
plot(idx, T_clean.old, '-o', 'LineWidth', 1.5, 'MarkerSize', 5); %[output:9a045229]
plot(idx, T_clean.new, '-s', 'LineWidth', 1.5, 'MarkerSize', 5); %[output:9a045229]
hold off; %[output:9a045229]

xlabel('Row Index'); %[output:9a045229]
ylabel('Value'); %[output:9a045229]
title('Old and New: Values by Row'); %[output:9a045229]
legend('Old', 'New', 'Location', 'best'); %[output:9a045229]
grid on; %[output:9a045229]
box on; %[output:9a045229]

% 5.2 histogram comparison
figure('Name', 'Distribution Comparison', 'NumberTitle', 'off'); %[output:8d1c792b]
[~, binEdges] = histcounts([T_clean.old; T_clean.new], 'BinWidth', 5);

hold on; %[output:8d1c792b]
histogram(T_clean.old, binEdges, 'FaceAlpha', 0.5); %[output:8d1c792b]
histogram(T_clean.new, binEdges, 'FaceAlpha', 0.5); %[output:8d1c792b]
hold off; %[output:8d1c792b]

xlabel('Value'); %[output:8d1c792b]
ylabel('Frequency'); %[output:8d1c792b]
title('Distribution Comparison'); %[output:8d1c792b]
legend('Old', 'New', 'Location', 'best'); %[output:8d1c792b]
grid on; %[output:8d1c792b]
box on; %[output:8d1c792b]

% 5.3 boxplot comparison
figure('Name', 'Boxplot Comparison', 'NumberTitle', 'off'); %[output:5ef19cf7]
boxplot(T_clean{:, :}, 'Labels', {'Old', 'New'}); %[output:5ef19cf7]

ylabel('Value'); %[output:5ef19cf7]
title('Median, Quartiles and Spread'); %[output:5ef19cf7]
grid on; %[output:5ef19cf7]
box on; %[output:5ef19cf7]

% 5.4 summary statistics in the original units
figure('Name', 'Summary Statistics', 'NumberTitle', 'off'); %[output:3be7ffd5]

summaryStats = [
    mean_old, mean_new;
    median_old, median_new;
    std_old, std_new;
    iqr_old, iqr_new;
    range_old, range_new
    ];

bar(summaryStats, 'grouped'); %[output:3be7ffd5]

xticks(1:5); %[output:3be7ffd5]
xticklabels({'Mean', 'Median', 'Std', 'IQR', 'Range'}); %[output:3be7ffd5]
ylabel('Value (original units)'); %[output:3be7ffd5]
title('Summary Statistics: Old vs New'); %[output:3be7ffd5]
legend('Old', 'New', 'Location', 'best'); %[output:3be7ffd5]
grid on; %[output:3be7ffd5]
box on; %[output:3be7ffd5]

% 5.5 coefficient of variation — separate percentage scale
if all([mean_old, mean_new] > 0) %[output:group:081a94da]
    cvValues = [std_old, std_new] ./ [mean_old, mean_new] * 100;
    figure('Name', 'Coefficient of Variation', 'NumberTitle', 'off'); %[output:33855219]

    bar(cvValues); %[output:33855219]
    xticks([1 2]);   %[output:33855219]
    xticklabels({'Old', 'New'}); %[output:33855219]
    ylabel('CV (%)'); %[output:33855219]
    title('Relative Variability'); %[output:33855219]
    grid on; %[output:33855219]
    box on; %[output:33855219]

    text(1, cvValues(1), sprintf('%.2f%%', cvValues(1)), ... %[output:33855219]
        'HorizontalAlignment', 'center', ... %[output:33855219]
        'VerticalAlignment', 'bottom'); %[output:33855219]
    text(2, cvValues(2), sprintf('%.2f%%', cvValues(2)), ... %[output:33855219]
        'HorizontalAlignment', 'center', ... %[output:33855219]
        'VerticalAlignment', 'bottom'); %[output:33855219]
    ylim([0, max([cvValues, 1]) * 1.2]); %[output:33855219]

else
    warning('CV plot skipped because a group mean is not positive.');
end %[output:group:081a94da]

% 5.6 summary comparison
figure('Name', 'Summary', 'NumberTitle', 'off'); %[output:4670c91f]

sum_old = [min_old, Q1_old, median_old, Q3_old, max_old];
sum_new = [min_new, Q1_new, median_new, Q3_new, max_new];

x = 1:5;

hold on; %[output:4670c91f]
plot(x, sum_old, '-o', 'LineWidth', 2, 'MarkerSize', 8); %[output:4670c91f]
plot(x, sum_new, '-s', 'LineWidth', 2, 'MarkerSize', 8); %[output:4670c91f]
hold off; %[output:4670c91f]

xticks(1:5); %[output:4670c91f]
xticklabels({'Min', 'Q1', 'Median', 'Q3', 'Max'}); %[output:4670c91f]
xlim([0.8, 5.2]); %[output:4670c91f]
ylabel('Value'); %[output:4670c91f]
title('Summary Comparison'); %[output:4670c91f]
legend('Old', 'New', 'Location', 'best'); %[output:4670c91f]
grid on; %[output:4670c91f]
box on; %[output:4670c91f]


